package os.aios.core;
import android.app.Instrumentation;import android.net.Uri;import android.os.Bundle;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.UUID;import org.json.*;import os.aios.runtime.CoreRuntimeClient;
/** End-to-end acceptance through the signature IPC boundary, against real device SQLite/files. */
public final class CoreRuntimeAcceptance extends Instrumentation{
 private int count;private CoreRuntimeClient core;private void check(boolean v,String label){if(!v)throw new AssertionError(label);count++;}private void rejected(Throwing r,String label)throws Exception{try{r.run();}catch(Exception expected){count++;return;}throw new AssertionError(label);}interface Throwing{void run()throws Exception;}
 private JSONObject ws(String action,JSONObject p)throws Exception{return core.call("workspace",action,p).getJSONObject("data");}
 public void onCreate(Bundle b){super.onCreate(b);start();}public void onStart(){Bundle out=new Bundle();String skill=null;try{core=new CoreRuntimeClient(getTargetContext());JSONObject status=core.call("automation","status",new JSONObject());check(status.getString("owner_process").equals("os.aios.core"),"Core owns Event Runtime");check(ws("task.list",new JSONObject()).has("items"),"Workspace IPC");
  String grant="acceptance:"+UUID.randomUUID();core.call("automation","authorization.put",new JSONObject().put("id",grant).put("subject","instrumentation").put("task_id","acceptance").put("approved_version",1).put("capabilities",new JSONArray().put("scheduler.execute").put("context.process")).put("resources",new JSONArray().put("screen:test").put("content://test/resource")));
  JSONObject lease=core.call("automation","resource.acquire",new JSONObject().put("authorization_id",grant).put("owner","acceptance-a").put("resource","screen:test").put("ttl_ms",60000));check(lease.getString("resource").equals("screen:test"),"Resource lease");rejected(()->core.call("automation","resource.acquire",new JSONObject().put("authorization_id",grant).put("owner","acceptance-b").put("resource","screen:test")),"Resource contention");core.call("automation","resource.release",new JSONObject().put("owner","acceptance-a"));
  String graph="acceptance-"+UUID.randomUUID();core.call("automation","graph.put",new JSONObject().put("id",graph).put("nodes",new JSONArray().put(new JSONObject().put("id","event").put("kind","trigger").put("trigger",new JSONObject().put("type","topic").put("topic","automation.acceptance.ready").put("equals",new JSONObject().put("generation",1)))).put(new JSONObject().put("id","work").put("kind","action"))).put("edges",new JSONArray().put(new JSONObject().put("from","event").put("to","work"))));JSONObject run=core.call("automation","run.start",new JSONObject().put("graph_id",graph).put("occurrence","one").put("authorization_id",grant));check(run.getJSONArray("nodes").getJSONObject(0).getString("state").equals("waiting_trigger"),"Topic trigger waits");core.call("events","publish",new JSONObject().put("topic","automation.acceptance.ready").put("source_id","acceptance").put("source_version","1").put("critical",true).put("data",new JSONObject().put("generation",1)));JSONObject ready=core.call("automation","run.ready",new JSONObject().put("id",run.getString("id")));check(ready.getJSONArray("items").length()==1,"Hub dispatches Scheduler trigger");
  JSONObject created=ws("skill.create",new JSONObject().put("title","Acceptance "+UUID.randomUUID()).put("description","asset publication").put("content_md","# Test\nUse the reference.").put("assets",new JSONObject().put("scripts/check.js","return true;").put("references/source.md","evidence")));skill=created.getString("id");JSONObject loaded=ws("skill.get",new JSONObject().put("id",skill));check(loaded.getJSONObject("assets").length()==2,"Skill assets load atomically");JSONObject updated=ws("skill.update",new JSONObject().put("id",skill).put("expected_revision",loaded.getLong("revision")).put("content_md","# Changed"));JSONObject rolled=ws("skill.rollback",new JSONObject().put("id",skill).put("expected_revision",updated.getLong("revision")).put("target_revision",1));check(rolled.getString("content_md").contains("Use the reference"),"Skill rollback");
  JSONObject processors=core.call("processing","capabilities",new JSONObject());boolean ocr=false,text=false;for(int i=0;i<processors.getJSONArray("items").length();i++){JSONObject c=processors.getJSONArray("items").getJSONObject(i);if(c.getString("id").equals("image.ocr"))ocr=!c.getBoolean("available")&&!c.getString("reason").isBlank();if(c.getString("id").equals("text.extract"))text=c.getBoolean("available");}check(ocr&&text,"Processing availability is explicit");
  Uri channel=core.allocateDataChannel();try(OutputStream stream=core.openOutput(channel)){stream.write("large-channel".getBytes(StandardCharsets.UTF_8));}try(InputStream stream=core.openInput(channel)){check(new String(stream.readAllBytes(),StandardCharsets.UTF_8).equals("large-channel"),"FD data channel");}core.release(channel);
  JSONObject harnesses=ws("runtime.harness.list",new JSONObject());check(harnesses.getJSONArray("items").length()>0,"Harness registration");out.putString("stream","PASS: "+count+" Core Runtime terminal-layer assertions\n");finish(-1,out);
 }catch(Throwable e){out.putString("stream","FAIL after "+count+": "+android.util.Log.getStackTraceString(e));finish(0,out);}finally{if(skill!=null)try{JSONObject current=ws("skill.get",new JSONObject().put("id",skill));ws("skill.delete",new JSONObject().put("id",skill).put("expected_revision",current.getLong("revision")));}catch(Exception ignored){}}}
}
